function ultimaResposta(c : chat) : string {
    return c.perguntas[c.respostas.length]
}

class N46 {
    s : string = ""
    m : string = ""
}

function reika(no : string) : N64 {
    let snm : N46 = { s : "", m : ""}

    for (let i : number = 0; i < no.length; i++) {
        if (i % 2 == 0) {
            snm.s = snm.s + no[i]
        } else {
            snm.m = no[i] + snm.m
        }
    }

    return snm
}

